export const CI_CONCLUSION = Object.freeze({
  SUCCESS:   "success",
  FAILURE:   "failure",
  CANCELLED: "cancelled",
  NEUTRAL:   "neutral",
  TIMED_OUT: "timed_out",
  ACTION_REQUIRED: "action_required",
});

