} from "@/components/ui";
import { formatDistanceToNow } from "date-fns";
import clsx from "clsx";

const REPOS = [
  { owner: "xjeddah", name: "MyShell" },
  { owner: "xjeddah", name: "QwenPaw" },
];

const STATUS_VARIANT: Record<string, string> = {
  analyzing: "blue",
  generating: "amber",
  submitted: "green",
