@import "tailwindcss";

@theme {
  --font-mono: 'JetBrains Mono', monospace;
  --font-sans: 'DM Sans', sans-serif;
  --font-display: 'Syne', sans-serif;

  --color-surface-0: #0a0a0b;
  --color-surface-1: #111114;
  --color-surface-2: #18181c;
  --color-surface-3: #222228;
  --color-surface-4: #2e2e36;

  --color-border: #2e2e36;
  --color-border-bright: #44444f;

  --color-text-primary: #e8e8f0;
  --color-text-secondary: #8e8ea0;
  --color-text-tertiary: #5a5a6e;

  --color-accent-green: #00d97e;
  --color-accent-red: #ff4d6a;
  --color-accent-amber: #ffb547;
  --color-accent-blue: #4d9fff;
  --color-accent-purple: #a78bfa;

  --color-brand: #1D9E75;

  --animate-fade-in: fadeIn 0.2s ease-out;
  --animate-slide-up: slideUp 0.25s ease-out;
  --animate-pulse-dot: pulseDot 2s ease-in-out infinite;
  --animate-shimmer: shimmer 1.5s ease-in-out infinite;

  @keyframes fadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
  }
  @keyframes slideUp {
    from { opacity: 0; transform: translateY(8px); }
    to { opacity: 1; transform: translateY(0); }
  }
  @keyframes pulseDot {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.3; }
  }
  @keyframes shimmer {
    0% { background-position: 200% 0; }
    100% { background-position: -200% 0; }
  }
}

@layer base {
  * { box-sizing: border-box; }

  html, body {
    background-color: var(--color-surface-0);
    color: var(--color-text-primary);
    font-family: var(--font-sans);
    -webkit-font-smoothing: antialiased;
  }

  ::-webkit-scrollbar { width: 4px; height: 4px; }
  ::-webkit-scrollbar-track { background: transparent; }
  ::-webkit-scrollbar-thumb { background: var(--color-surface-4); border-radius: 2px; }
  ::-webkit-scrollbar-thumb:hover { background: var(--color-border-bright); }

  ::selection { background: rgba(0, 217, 126, 0.2); color: var(--color-text-primary); }
}

@layer components {
  .card {
    @apply bg-surface-1 border border-border rounded-lg;
  }
  .card-header {
    @apply flex items-center gap-2 px-4 py-3 border-b border-border;
  }
  .badge {
    @apply inline-flex items-center gap-1 px-2 py-0.5 rounded text-xs font-mono font-medium;
  }
  .btn {
    @apply inline-flex items-center gap-1.5 px-3 py-1.5 rounded text-sm font-medium
           border border-border bg-surface-2 text-text-primary
           hover:bg-surface-3 hover:border-border-bright
           transition-all duration-150 cursor-pointer;
  }
  .btn-primary {
    @apply bg-accent-green/10 border-accent-green/40 text-accent-green
           hover:bg-accent-green/20 hover:border-accent-green/60;
  }
  .shimmer {
    background: linear-gradient(
      90deg,
      var(--color-surface-2) 25%,
      var(--color-surface-3) 50%,
      var(--color-surface-2) 75%
    );
    background-size: 200% 100%;
    animation: var(--animate-shimmer);
  }
  .status-dot {
    @apply w-1.5 h-1.5 rounded-full shrink-0;
  }
}

