    refreshInterval: 60000,
  });

  const rules = data?.data ?? [];
  const meta = data?.meta ?? {};

  async function handleSave() {
    if (!editing) return;
    setSaving(true);
    try {
      await updateBranchRule(String(editing.repo_owner), String(editing.repo_name), String(editing.pattern), editing);
      mutate();
      setEditing(null);
