                      </span>
                      {w.path !== "*" && (
                        <span className="text-[10px] font-mono text-text-tertiary">{w.path}</span>
                      )}
                      <span className="text-xs text-text-primary">{w.message}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}

