          <div className="flex flex-wrap gap-2 items-center mb-4">
            <select
              value={simRepo}
              onChange={(e) => setSimRepo(e.target.value)}
              className="bg-surface-2 border border-border rounded px-2 py-1.5 text-xs text-text-primary"
