            <span className="text-text-tertiary text-xs">to</span>
            <input
              type="date"
              value={simTo}
              onChange={(e) => setSimTo(e.target.value)}
              className="bg-surface-2 border border-border rounded px-2 py-1.5 text-xs text-text-primary"
              title="To date (default: now)"
            />
