              </button>
            </div>

            {diffError && (
              <div className="rounded-lg border border-red-500/30 bg-red-500/5 px-4 py-3 mb-4">
                <div className="text-red-400 text-sm font-mono mb-1">Comparison failed</div>
                <div className="text-red-400/70 text-xs">{diffError}</div>
              </div>
