  try { docker("rm", "-f", "gitwire-proof-app"); } catch {}
  try { docker("rm", "-f", pgCid); } catch {}
  try { docker("rm", "-f", redisCid); } catch {}
  try { docker("network", "rm", networkName); } catch {}
  console.log("\ncleanup: containers + network removed");
}

