    actor:     data.actor,
    actorType: "human",
    repoFullName: data.repoFullName,
    principalId: data.principalId ?? null,
    surfaceId: data.surfaceId || "audit_trail:vulnerability_dismissed",
    payload: {
      package_name: data.packageName,
      ghsa_id:      data.ghsaId,
      severity:     data.severity,
      reason:       data.reason,
    },
  }),

  /** Flaky test quarantined */
  quarantine: (data) => appendEntry({
    category:  "quarantine",
    eventType: "test_quarantined",
    actor:     "gitwire[bot]",
    actorType: "bot",
    repoFullName: data.repoFullName,
    principalId: data.principalId ?? null,
    surfaceId: data.surfaceId || "audit_trail:quarantine",
    payload: {
      test_count: data.testCount,
      tests:      data.tests,
      pr_number:  data.prNumber,
    },
  }),

  /** Review gate blocked a merge */
  reviewGateBlock: (data) => appendEntry({
    category:  "review_gate",
