    ...WORKER_SURFACES,
    ...SCHEDULED_SURFACES,
    ...INGRESS_SURFACES,
  ]);
  REGISTERED = true;
}

export function expectedProtectedSurfaceIds() {
  return [
    ...ROUTE_SURFACES,
    ...WORKER_SURFACES,
    ...SCHEDULED_SURFACES,
    ...INGRESS_SURFACES,
  ].map((s) => s.id);
}

