      conditions.push(`cr.conclusion = $${idx++}`);
      values.push(conclusion);
    }
    if (healStatus) {
      conditions.push(`cr.heal_status = $${idx++}`);
      values.push(healStatus);
    }
    if (branch) {
      conditions.push(`cr.branch = $${idx++}`);
      values.push(branch);
    }

