const __dirname = path.dirname(fileURLToPath(import.meta.url));
const TEMPLATES_DIR = path.resolve(__dirname, "../../templates");

// ── Template registry ──────────────────────────────────────────────────────
// Metadata is defined here (not parsed from YAML) so we control labels,
