    const unauthedStatuses = results.filter(r => !r.authed).map(r => r.status);
    authedStatuses.forEach(h => expect(["expected"]).toContain(h === "expected" ? "expected" : "unexpected"));
    unauthedStatuses.forEach(s => expect(s).toBe(401));
