export function validateBurstReport(report, opts = {}) {
  if (!report || typeof report !== "object" || Array.isArray(report)) {
    throw Object.assign(
      new Error("validateBurstReport: report must be a non-null object"),
      { code: "INVALID_VALIDATOR_ARG" }
    );
  }

