      spec = attempts[cursor];
      cursor++;
    } else if (onExhausted === "repeat_last" && attempts.length > 0) {
      spec = attempts[attempts.length - 1];
    } else {
      throw Object.assign(
        new Error(`scenario: attempts exhausted (consumed ${cursor})`),
        { code: SCENARIO_EXHAUSTED }
      );
    }

    if (spec && typeof spec === "object" && spec.throw instanceof Error) {
      trace.append({ kind: "attempt_throw", scenarioOperationId, detail: { code: spec.throw.code || null } });
      throw spec.throw;
    }

    // Deferred spec: block on the caller-controlled gate. A fulfilled value
    // is normalized through mockOutcome (so the engine receives a valid
    // ClassifiedOutcome); a rejected gate stays an escaped rejection. The
    // gate is tracked in pendingGates so cleanup can cancel a blocked run.
    // The gate is validated BEFORE tracking so a malformed gate cannot enter
    // pendingGates (where cleanup would later call gate.reject and throw).
    if (spec && typeof spec === "object" && Object.prototype.hasOwnProperty.call(spec, "deferred")) {
      const gate = spec.deferred;
      validateDeferredGate(gate);
      pendingGates.add(gate);
      let value;
      try {
        value = await gate.promise;
      } finally {
        pendingGates.delete(gate);
      }
      // cleanup() may have rejected the gate with SCENARIO_CANCELLED while
      // we were awaiting — that rejection propagates as the awaited value's
      // rejection, so we never reach this branch on cancellation. A genuine
      // fulfillment runs through mockOutcome.
      const outcome = mockOutcome(value);
      trace.append({
        kind: "attempt_settle",
        scenarioOperationId,
        detail: { transport: outcome.transport, status: outcome.status, deferred: true },
      });
      return outcome;
    }

    const outcome = mockOutcome(spec);
    trace.append({
      kind: "attempt_settle",
      scenarioOperationId,
      detail: { transport: outcome.transport, status: outcome.status },
    });
    return outcome;
  };

  // Wrap run so every invocation tracks its outer promise. The tracking Set
  // is what cleanup() drains; the safety catch is attached in cleanup() to
  // any promise still in the Set at drain time, so fire-and-forget callers
  // don't leak unhandled rejections.
  const trackedRun = (...args) => {
    const p = run(...args);
    activeRuns.add(p);
    // Self-remove on settle. The .finally callback itself cannot throw, so
    // its returned promise resolves cleanly; we attach a safety .catch on
    // that returned promise so a rejecting p does not propagate through the
    // finally chain as an unhandled rejection (finally re-throws the
    // original rejection, which would otherwise have no consumer).
    p.finally(() => activeRuns.delete(p)).catch(() => { /* safety */ });
    return p;
  };

  const pendingDeferredCount = () => pendingGates.size;

  // Concurrent-cleanup join: the first cleanup call drives the drain; every
  // subsequent concurrent call receives the SAME promise. This prevents an
  // afterEach or caller from continuing while deferred cancellation and run
  // settlement are still incomplete (a second `if (closing) return` would
  // resolve immediately, racing the first drain).
  let cleanupPromise = null;
  const cleanup = () => {
    if (cleanupPromise) return cleanupPromise;
    cleanupPromise = (async () => {
      closing = true;
      // Snapshot the gates BEFORE rejecting them. Each run()'s finally block
      // removes its gate from pendingGates when the rejection propagates, so
      // by the time we reach the trace.append below, pendingGates is empty
      // and a naive count would record zero. Capture the count here.
      const gatesToCancel = [...pendingGates];
      const cancelError = Object.assign(
        new Error("scenario: cleanup cancelled pending deferred"),
        { code: SCENARIO_CANCELLED }
      );
      for (const gate of gatesToCancel) {
        gate.reject(cancelError);
      }
      // Snapshot pending runs. Attach a safety catch to each BEFORE awaiting
      // so any that reject during the allSettled drain cannot surface as
      // unhandledRejection (allSettled itself does not count as a handler for
      // Node's unhandled-rejection detection in some runtimes; the explicit
      // catch is the portable guarantee).
      const pending = [...activeRuns];
      for (const p of pending) p.catch(() => { /* safety — see trackedRun */ });
      await Promise.allSettled(pending);
      activeRuns.clear();
      pendingGates.clear();
      trace.append({
        kind: "scenario_cleanup",
        detail: { consumedAttempts: cursor, cancelledDeferreds: gatesToCancel.length },
      });
    })();
    return cleanupPromise;
  };

  return Object.freeze({
    run: trackedRun,
    cleanup,
    pendingDeferredCount,
    trace,
  });
}

