    expect(result.httpUnexpected).toBe(0);
    expect(result.httpNotReceived).toBe(0);
    expect(result.assertionFailed).toBe(0);
  });

  it("/health endpoint is NOT rate limited", async () => {
    const ops = Array.from({ length: 50 }, () => ({
      kind: "health",
      method: "GET",
      run: () => httpOperation({
