    process.env.GITWIRE_VALIDATOR_IMAGE_REF = "reg/v@sha256:" + "a".repeat(64);
    process.env.GITWIRE_VALIDATOR_IMAGE_DIGEST = "sha256:" + "a".repeat(64);

