        command_results: [{ command: "lint", exit_status: 0, output_hash: "sha256:x", duration_ms: 5 }],
        network_disabled: true, non_root: true, read_only_rootfs: true,
      }),
    }));
    try {
      const r = await executorServiceBackend.run({
        files: [{ path: "x", content: "y" }],
        commands: ["lint"],
