  test("duplicate planned step IDs → divergent", () => {
    const plan = planWith([DESCRIPTOR_STEP, DESCRIPTOR_STEP]);
    const exec = execWith([DESCRIPTOR_EXECUTED, DESCRIPTOR_EXECUTED]);
