    const plan = planWith([{ ...DESCRIPTOR_STEP, step_id: "lint_result:0" }, { ...DESCRIPTOR_STEP, step_id: "test_or_build_result:0", argv: ["node", "test.js"], target_paths: ["test.js"] }]);
