      category: "integration",
      status: "pass",
      blocking: false,
      detail: "10 event(s) in last 7 days",
    },
    {
      id: "gitwire_yml_found",
      label: "Policy file configured",
      category: "policy",
      status: "pass",
      blocking: false,
      detail: "3 repo(s) with config overrides",
    },
    {
