    expect(resource).toEqual({
      type: "installation",
      installationId: "99001",
      organization: "octo",
      repository: "repo",
    });
  });

  it("represents aggregate HTTP operations as fleet resources", async () => {
    await expect(resolveResource("fleet", {})).resolves.toEqual({ type: "fleet" });
